n class="badge badge-soft-info"><?=$c['status']?></span></td><td><a class="btn btn-outline-primary btn-sm" href="index.php?page=compliance_download_contribution&id=<?=$c['id']?>">CSV</a><?php if($isAdmin):?><button class="btn btn-outline-secondary btn-sm edit-contribution" data-json='<?=htmlspecialchars(json_encode($c),ENT_QUOTES)?>'>Edit</button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$contributions):?><div class="text-center text-secondary py-4">No contributions for this period.</div><?php endif;?></div>
