<script>$(function(){const post=(url,form)=>$.ajax({url,type:'POST',data:form,processData:!(form instanceof FormData),contentType:form instanceof FormData?false:'application/x-www-form-urlencoded',dataType:'json'}).done(r=>{if(r.status==='success'){showToast('success',r.message);setTimeout(()=>location.reload(),700)}else Swal.fire('Error',r.message,'error')}).fail(x=>Swal.fire('Error',x.responseJSON?.message||'Request failed.','error'));let table=$('#recordsTable').DataTable({pageLength:10});$('#agencyFilter').change(function(){table.column(<?=$isAdmin?1:0?>).search(this.value).draw();updateExport()});$('#recordStatusFilter').change(function(){table.column(<?=$isAdmin?3:2?>).search(this.value).draw();updateExport()});function updateExport(){$('#exportBtn').attr('href','index.php?page=compliance_export_report&agency='+encodeURIComponent($('#agencyFilter').val())+'&status='+encodeURIComponent($('#recordStatusFilter').val()))}$('.submit-record').click(function(){let r=$(this).data('json');$('#recordId').val(r.id);$('#recordAgency').text(r.agency);$('#recordNumber').val(r.record_number||'');bootstrap.Modal.getOrCreateInstance('#recordModal').show()});$('#recordForm').submit(function(e){e.preventDefault();post('index.php?page=compliance_submit_record',new FormData(this))});$('.correct-record').click(function(){let r=$(this).data('json');$('#correctionRecordId').val(r.id);$('#proposedValue').val(r.record_number);bootstrap.Modal.getOrCreateInstance('#correctionModal').show()});$('#correctionForm').submit(function(e){e.preventDefault();post('index.php?page=compliance_request_correction',new FormData(this))});$('.review-record').click(function(){let r=$(this).data('json');$('#reviewId').val(r.id);$('#reviewSummary').text(r.first_name+' '+r.last_name+' · '+r.agency+' · '+r.record_number);bootstrap.Modal.getOrCreateInstance('#reviewModal').show()});$('#reviewForm').submit(function(e){e.preventDefault();post('index.php?page=compliance_review_record',$(this).serialize())});$('.decide-correction').click(function(){$('#decisionId').val($(this).data('id'));bootstrap.Modal.getOrCreateInstance('#decisionModal').show()});$('#decisionForm').submit(function(e){e.preventDefault();post('index.php?page=compliance_decide_correction',$(this).serialize())});$('.edit-contribution').click(function(){let c=$(this).data('json');$('#contributionId').val(c.id);$('#contributionTitle').text('Edit Contribution');$('#newContribution').addClass('d-none');$('#editAmounts').removeClass('d-none');$('#grossSalary').val(c.gross_salary);for(let n of ['sss_employee','sss_employer','philhealth_employee','philhealth_employer','pagibig_employee','pagibig_employer','bir_tax_withheld'])$('#field_'+n).val(c[n]);$('#contributionRemarks').val(c.admin_remarks);bootstrap.Modal.getOrCreateInstance('#contributionModal').show()});$('#contributionModal').on('hidden.bs.modal',function(){$('#contributionId').val('');$('#contributionTitle').text('Add Contribution');$('#newContribution').removeClass('d-none');$('#editAmounts').addClass('d-none');this.querySelector('form').reset()});$('#contributionForm').submit(function(e){e.preventDefault();post('index.php?page='+($('#contributionId').val()?'compliance_update_contribution':'compliance_generate'),$(this).serialize())})});</script>
